CREATE FUNCTION agri.covariate_vector_manifest(p_cell_id uuid, p_window_start timestamp with time zone, p_window_end timestamp with time zone, p_as_of_time timestamp with time zone, p_schema_version character varying) RETURNS TABLE(schema_version text, cell_id uuid, window_start timestamp with time zone, window_end timestamp with time zone, as_of_time timestamp with time zone, feature_count integer, day_count integer, emitted_row_count integer, complete_row_count integer, partial_row_count integer, imputed_row_count integer, complete_day_count integer, feature_names text[], declared_gaps jsonb, source_release_ids uuid[], max_data_available_at timestamp with time zone, manifest_checksum text)
    LANGUAGE sql STABLE
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, MDY'
    SET extra_float_digits TO '1'
    SET search_path TO 'public', 'pg_catalog'
    AS $$
    WITH feature AS (
        SELECT
            feature_row.observed_date,
            feature_row.feature_index,
            feature_row.feature_value,
            feature_row.input_count,
            feature_row.expected_input_count,
            feature_row.is_imputed,
            feature_row.data_available_at
        FROM agri.covariate_daily_features(
            p_cell_id,
            p_window_start,
            p_window_end,
            p_as_of_time,
            p_schema_version
        ) AS feature_row
    ),
    lookback AS (
        SELECT agri.covariate_lookback_days(p_schema_version) AS lookback_days
    ),
    schema_names AS (
        SELECT array_agg(schema_entry.feature_name ORDER BY schema_entry.feature_index) AS feature_names,
               count(*)::integer AS feature_count
        FROM agri.covariate_feature_schema(p_schema_version) AS schema_entry
    ),
    gaps AS (
        SELECT coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'stream_key', gap.stream_key,
                    'gap_kind', gap.gap_kind,
                    'gap_reason', gap.gap_reason
                )
                ORDER BY gap.stream_key
            ),
            '[]'::jsonb
        ) AS declared_gaps
        FROM agri.covariate_declared_gap(p_schema_version) AS gap
    ),
    lineage AS (
        SELECT
            coalesce(
                array_agg(DISTINCT signal.source_release_id ORDER BY signal.source_release_id),
                ARRAY[]::uuid[]
            ) AS source_release_ids
        FROM agri.signal_observation AS signal
        CROSS JOIN lookback
        WHERE signal.cell_id = p_cell_id
          AND signal.data_available_at <= p_as_of_time
          AND signal.support_key = 'surface'
          AND signal.quality_flag = 'accepted'
          AND signal.observed_at >= p_window_start - make_interval(days => lookback.lookback_days)
          AND signal.observed_at < p_window_end + interval '1 day'
    ),
    per_day AS (
        SELECT
            feature.observed_date,
            bool_and(feature.input_count = feature.expected_input_count) AS day_complete
        FROM feature
        GROUP BY feature.observed_date
    ),
    tally AS (
        SELECT
            count(DISTINCT feature.observed_date)::integer AS day_count,
            count(*)::integer AS emitted_row_count,
            count(*) FILTER (
                WHERE feature.input_count = feature.expected_input_count
            )::integer AS complete_row_count,
            count(*) FILTER (
                WHERE feature.input_count < feature.expected_input_count
            )::integer AS partial_row_count,
            count(*) FILTER (WHERE feature.is_imputed)::integer AS imputed_row_count,
            max(feature.data_available_at) AS max_data_available_at
        FROM feature
    )
    SELECT
        p_schema_version::text,
        p_cell_id,
        p_window_start,
        p_window_end,
        p_as_of_time,
        schema_names.feature_count,
        tally.day_count,
        tally.emitted_row_count,
        tally.complete_row_count,
        tally.partial_row_count,
        tally.imputed_row_count,
        (SELECT count(*) FILTER (WHERE per_day.day_complete) FROM per_day)::integer,
        schema_names.feature_names,
        gaps.declared_gaps,
        lineage.source_release_ids,
        tally.max_data_available_at,
        encode(
            digest(
                concat_ws(
                    '|',
                    'agri_covariate_vector_manifest_v1',
                    p_schema_version,
                    p_cell_id::text,
                    to_char(p_window_start AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
                    to_char(p_window_end AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
                    to_char(p_as_of_time AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
                    schema_names.feature_count::text,
                    array_to_string(schema_names.feature_names, ','),
                    tally.day_count::text,
                    tally.emitted_row_count::text,
                    tally.complete_row_count::text,
                    tally.partial_row_count::text,
                    tally.imputed_row_count::text,
                    (SELECT count(*) FILTER (WHERE per_day.day_complete) FROM per_day)::text,
                    gaps.declared_gaps::text,
                    array_to_string(lineage.source_release_ids, ','),
                    to_char(tally.max_data_available_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
                ),
                'sha256'
            ),
            'hex'
        ) AS manifest_checksum
    FROM tally
    CROSS JOIN schema_names
    CROSS JOIN gaps
    CROSS JOIN lineage
$$;
